clear all; clc; close all;
ObjectiveFunction = @Alsomitra_nondim3;

font=10;
set(groot, 'defaultAxesTickLabelInterpreter', 'latex'); 
set(groot, 'defaultLegendInterpreter', 'latex');
set(0,'defaultTextInterpreter','latex');
set(0, 'defaultAxesFontSize', font)
set(0, 'defaultLegendFontSize', font)
set(0, 'defaultAxesFontName', 'Times New Roman');
set(0, 'defaultLegendFontName', 'Times New Roman');
set(0, 'DefaultLineLineWidth', 0.7);

% Using SI units, instead of the units in LiJFM2022, is not a problem since the code is non dimensional 

% % Li et al validation
% l = 2.54*10^-2;   
% h = 0.15*10^-2;   
% rho_s = 1358;
% rho_f = 1000;


% l = 6.121914796;
% h = 0.61219148;
% rho_s = 5; % % % p(3) = 1.4*10^3; % p(3) = 1.4 LiJFM2022 
% rho_f = 1;    % % % p(4) = 1.225; % p(4) = 1.225*10^-3; LiJFM2022 

l_CE = 0;     % % % p(5) = p(1)*0.0;
e_x = 0;       % % % p(6) = 0.00;
g = 9.80665;      % % % p(7) = 9.8066x5; % p(7) = 980.665; 
nu = 1; 

G_r = 0;
C_R = 1.1;
Ga = 30;
rho = 5;

chi = 10;

rho_f = 1;

rho_s = rho * rho_f;
h = ((Ga^2 * nu^2) / (g * chi^2 * (rho - 1)))^(1/3);
l = h * chi;

U_g = sqrt((rho_s/rho_f - 1) * g * h);

p = [l h rho_s rho_f l_CE e_x g G_r nu C_R]';

% [x_,y_,tSol,v_yp,v_xp,omega,theta] = ObjectiveFunction(p);

% % %%%%%% START OF SWEEP CODE %%%%%

% Fixed parameters
l_CE  = 0;
e_x   = 0;
g     = 9.80665;
nu    = 1;
rho_f = 1;
chi   = 10;

% Define this before running
% C_R = 1.1;

% Sweep values
rho_vals = unique(5:3:150);
Ga_vals  = 10:1:10;
Gr_vals  = 1:5;

nRho = numel(rho_vals);
nGa  = numel(Ga_vals);
nGr  = numel(Gr_vals);

% Averaging window
avgStart = 25;
avgEnd   = 30;

% Output arrays (minimal storage)
maxGain  = nan(nGa, nGr);
rhoAtMax = nan(nGa, nGr);

% Main sweep
for iGa = 1:nGa
    Ga = Ga_vals(iGa);

    fprintf('\n=== Ga = %.2f ===\n', Ga);

    % Store only temporary gains for this Ga
    gainThisGa = nan(nRho, nGr);

    for iRho = 1:nRho
        rho = rho_vals(iRho);

        % Dimensional parameters
        rho_s = rho * rho_f;
        h = ((Ga^2 * nu^2) / (g * chi^2 * (rho - 1)))^(1/3);
        l = h * chi;

        % -------------------------------
        % Baseline (Gr = 0)
        % -------------------------------
        p0 = [l; h; rho_s; rho_f; l_CE; e_x; g; 0; nu; C_R];
        [~, y0, t0, ~, ~, ~, ~] = ObjectiveFunction(p0);

        idx0 = (t0 >= avgStart) & (t0 <= avgEnd);

        if ~any(idx0)
            continue
        end

        y0_avg = mean(y0(idx0));
        clear y0 t0

        % -------------------------------
        % Gust cases
        % -------------------------------
        for iGr = 1:nGr
            G_r = Gr_vals(iGr);

            p1 = [l; h; rho_s; rho_f; l_CE; e_x; g; G_r; nu; C_R];
            [~, y1, t1, ~, ~, ~, ~] = ObjectiveFunction(p1);

            idx1 = (t1 >= avgStart) & (t1 <= avgEnd);

            if any(idx1)
                y1_avg = mean(y1(idx1));
                gainThisGa(iRho, iGr) = y1_avg - y0_avg;
            end

            clear y1 t1
        end

        fprintf('rho = %.2f done\n', rho);
    end

    % -------------------------------
    % Extract maxima for this Ga
    % -------------------------------
    for iGr = 1:nGr
        col = gainThisGa(:, iGr);

        if any(~isnan(col))
            [maxGain(iGa,iGr), idx] = max(col, [], 'omitnan');
            rhoAtMax(iGa,iGr) = rho_vals(idx);
        end
    end
end

% Print results
fprintf('\nRESULTS:\n');
for iGa = 1:nGa
    fprintf('\nGa = %d\n', Ga_vals(iGa));
    for iGr = 1:nGr
        fprintf('Gr = %d → rho_max = %.3f, yG_max = %.4f\n', ...
            Gr_vals(iGr), rhoAtMax(iGa,iGr), maxGain(iGa,iGr));
    end
end

% Plot: rho at max elevation gain vs G_R (one tile per Ga)
figure;
tiledlayout(2,5, 'TileSpacing','compact', 'Padding','compact');

for iGa = 1:nGa
    nexttile;
    hold on; grid on; box on;

    plot(Gr_vals, rhoAtMax(iGa,:), '-o', ...
        'LineWidth',1.5, 'MarkerSize',6);

    xlabel('$G_{\mathrm{R}}$', 'Interpreter','latex');
    ylabel('$\rho_{\max(y_\mathrm{G})}$', 'Interpreter','latex');

    title(sprintf('$Ga = %d$', Ga_vals(iGa)), ...
        'Interpreter','latex', 'FontSize',14, 'FontWeight','bold');

    text(-0.2, 1.08, sprintf('(%c)', 'a'+iGa-1), ...
        'Units','normalized', 'Interpreter','latex', ...
        'FontWeight','bold');

    set(gca, 'FontSize',11, 'TickLabelInterpreter','latex');
end

sgtitle('Density ratio at maximum elevation gain', ...
    'Interpreter','latex', 'FontSize',16, 'FontWeight','bold');

