%     'FaceAlpha',0.3, ...
%     'EdgeColor','none', ...
%     'HandleVisibility','off');
% 
% plot(ax1, tSol, v_xp, 'b', 'LineWidth', lw_plot);
% plot(ax1, ux_x{Gr}, ux_y{Gr}, ...
%     'Color', [34 197 94]/255, ...
%     'LineWidth', lw_plot);
% 
% grid(ax1,'on')
% box(ax1,'on')
% xlim(ax1,[14.8 28]);
% ylim(ax1,[-3.5 0.1]);
% 
% xlabel(ax1, '$t$', ...
%     'Interpreter','latex', ...
%     'FontSize', label_fs);
% 
% ylabel(ax1, '$u^\prime$', ...
%     'Interpreter','latex', ...
%     'FontSize', label_fs);
% 
% text(ax1, -0.2, 1.05, '(a)', ...
%     'Units','normalized', ...
%     'Interpreter','latex', ...
%     'FontWeight','bold', ...
%     'FontSize', panel_fs);
% 
% set(ax1, ...
%     'FontSize', tick_fs, ...
%     'LineWidth', lw_axes, ...
%     'TickLabelInterpreter', 'latex');
% 
% legend(ax1, 'Quasi-Steady','Pandi et al.', ...
