% 
% % %% Terminal Velocity check %%%
% % 
% % fig5 = figure;
% % plot(uy_x_curve_GR5_Ga30, uy_y_curve_GR5_Ga30, 'b', 'DisplayName','Model Result'); 
% % hold on
% % plot(x_curve30, y_curve30, 'Color', [34 197 94]/255, 'DisplayName','Extracted Terminal velocity');
% % grid on
% % xlabel('$t''\,[-]$'); ylabel('$u_y$ [-]')
% % xlim([19.8 32]);
% % ylim([-1.1 0]);
% % legend('show','Location','best')
% 
% %==============================
% % Define model data
% % ==============================
% 
% time = tSol;
% t_model = time;
% y_model = v_yp;
% 
% % ==============================
% % Define reference (digitised) data
% % ==============================
% 
% t_ref = uy_x_gr_5;
% y_ref = uy_y_gr_5;
% 
% % ==============================
% % Restrict comparison window
% % ==============================
% 
% t_min = 14.73;
% t_max = 27.05;
% 
% idx_ref   = (t_ref   >= t_min) & (t_ref   <= t_max);
% idx_model = (t_model >= t_min) & (t_model <= t_max);
% 
% t_ref_win   = t_ref(idx_ref);
% y_ref_win   = y_ref(idx_ref);
% 
% t_model_win = t_model(idx_model);
% y_model_win = y_model(idx_model);
% 
% % ==============================
% % Interpolate model onto reference time grid
% % ==============================
% 
% y_model_interp = interp1(t_model_win, y_model_win, t_ref_win, 'linear');
% 
% % Remove points where interpolation failed
% valid = ~isnan(y_model_interp);
% 
% t_common = t_ref_win(valid);
% y_ref_common = y_ref_win(valid);
% y_model_common = y_model_interp(valid);
% 
% % ==============================
% % Error in y at every time step
% % ==============================
% 
% y_err = y_model_common - y_ref_common;
% abs_y_err = abs(y_err);
% 
% % ==============================
% % Metrics
% % ==============================
% 
% MAE  = mean(abs_y_err);
% RMSE = sqrt(mean(y_err.^2));
% MaxAE = max(abs_y_err);range_ref = max(y_ref_common) - min(y_ref_common);
% 
% NMAE = MAE / range_ref * 100;
% 
% fprintf('Time window: %.1f–%.1f s\n', t_min, t_max);
% fprintf('Number of compared points: %d\n', length(t_common));
% fprintf('MAE   = %.6f deg\n', MAE);
% fprintf('RMSE  = %.6f deg\n', RMSE);
% fprintf('MaxAE = %.6f deg\n', MaxAE);
% fprintf('Normalized MAE (range-based): %.4f %%\n', NMAE);
% 
% % ==============================
% % Plot error in y vs time
% % ==============================
% 
% figure;
% plot(t_common, abs_y_err, 'r-', 'LineWidth', 1.2);
% grid on
% xlabel('$t\,[-]$', 'Interpreter', 'latex');
% ylabel('$|v_{model}-v_{ref}|\,[-]$', 'Interpreter', 'latex');
% title('Absolute alpha-error vs time');

%%% VALIDATION OF 3 DOF %%%
% 
% RGB = orderedcolors("gem");
% 
% fig6 = figure;
% ax = gca;
% ax.ColorOrder = RGB;
% hold on
% 
% GR_values = 0:5;
% t_all = {t_0, t_1, t_2, t_3, t_4, t_5};
% y_all = {y_0, y_1, y_2, y_3, y_4, y_5};
% 
% for i = 1:length(GR_values)
% 
%     if GR_values(i) == G_r
%         style = '-';   % solid for selected GR
%     else
%         style = '--';  % dashed for others
%     end
% 
%     plot(t_all{i}, y_all{i} - 1.939, style, 'LineWidth', 2, ...
%         'DisplayName', sprintf('GR = %d', GR_values(i)));
% end
% 
% % Model result (7th line → next color in palette cycle)
% plot(tSol, y_, '-', 'LineWidth', 2.5, 'DisplayName', sprintf('Quasi-Steady Result: GR = %d', G_r));
% grid on
% rectangle('Position', [15 -30 1 20], ... % [x, y, width, height]
%           'FaceColor', [0.5 0.5 0.5], ...
%           'FaceAlpha', 0.3, ...
%           'EdgeColor', 'none');
% xlabel('$t$,[-]'); 
% ylabel('$y$ [-]')
% 
% xlim([15 30]);
% ylim([-30 -10]);
% 
% legend('show','Location','best')
% 
% % Comparison for each time
% % ==============================
% % Define model data
% % ==============================
% 
% t_model = tSol;
% y_model = y_;
% 
% % ==============================
% % Define reference (digitised CFD) data
% % ==============================
% 
% t_ref = t_3;
% y_ref = y_3 -1.3372;
% 
% % ==============================
% % Restrict comparison window
% % ==============================
% 
% t_min = 16.03;
% t_max = 29.96;
% 
% idx_win = (t_ref >= t_min) & (t_ref <= t_max);
% t_ref_win = t_ref(idx_win);
% y_ref_win = y_ref(idx_win);
% 
% % ==============================
% % Interpolate model onto reference times
% % ==============================
% 
% y_model_interp = interp1(t_model, y_model, t_ref_win, 'linear', NaN);
% 
% % ==============================
% % Compute difference
% % ==============================
% 
% dy = y_model_interp - y_ref_win;
% 
% % Remove unmatched points
% valid = ~isnan(dy);
% t_plot = t_ref_win(valid);
% dy = dy(valid);
% y_ref_valid = y_ref_win(valid);
% 
% % ==============================
% % Quantitative metrics
% % ==============================
% 
% abs_dy = abs(dy);
% 
% mae = mean(abs_dy);          % Mean Absolute Error
% max_dy = max(abs_dy);        % Maximum Absolute Error
% 
% % Optional: relative absolute error (%)
% mean_ref = mean(abs(y_ref_valid));
% percent_error = (mae / mean_ref) * 100;
% 
% fprintf('Time window: %.2f–%.2f s\n', t_min, t_max);
% fprintf('Max |Δy|        : %.5f\n', max_dy);
% fprintf('Mean |Δy| (MAE) : %.5f\n', mae);
% fprintf('Mean ref |y|    : %.5f\n', mean_ref);
% fprintf('Percent MAE     : %.2f %%\n', percent_error);
% 
% % ==============================
% % Plot Δy vs time
% % ==============================
% 
% figure;
% plot(t_plot, dy, 'r.', 'MarkerSize', 8);
% grid on
% xlabel('$t\,[s]$', 'Interpreter', 'latex');
% ylabel('$\Delta y = y_{\mathrm{model}} - y_{\mathrm{ref}}$', 'Interpreter', 'latex');
% title('Local y-difference vs time');
% 
% % ==============================
% % Plot absolute difference
% % ==============================
% 
% figure;
% plot(t_plot, abs(dy), 'r.', 'MarkerSize', 8);
% grid on
% xlabel('$t\,[s]$', 'Interpreter', 'latex');
% ylabel('$|\Delta y|$', 'Interpreter', 'latex');
% title('Absolute local y-difference vs time');

%%%%

% RGB = orderedcolors("gem");
% 
% figure;
% tiledlayout(3,2, 'TileSpacing','compact', 'Padding','compact');
% 
% C_R = 1.1;
% 
% GR_values = 0:5;
% t_all = {t_0, t_1, t_2, t_3, t_4, t_5};
% y_all = {y_0, y_1, y_2, y_3, y_4, y_5};
% 
% % One marker time for each G_R panel
% marker_times = [20, 24, 25, 24, 20, 20];
% 
% results = struct();
% 
% % Consistent formatting
% title_fs  = 16;
% label_fs  = 14;
% tick_fs   = 12;
% panel_fs  = 14;
% lw_axes   = 1;
% lw_plot   = 1.4;
% lw_nogust = 0.9;
% 
% % ---------------------------------
% % Precompute no-gust quasi-steady data
% % ---------------------------------
% G_r0 = 0;
% p0 = [l h rho_s rho_f l_CE e_x g G_r0 nu C_R]';
% [~, y_nogust, t_nogust, ~, ~, ~, ~] = ObjectiveFunction(p0);
% 
% % Same colour as first panel
% nogust_color = RGB(1,:);
% 
% for i = 1:length(GR_values)
% 
%     G_r = GR_values(i);
% 
%     ax = nexttile;
%     hold(ax, 'on')
%     grid(ax, 'on')
%     box(ax, 'on')
% 
%     % Base colour for this gust ratio
%     base_c = RGB(i,:);
% 
%     % Reference data
%     t_ref = t_all{i};
%     y_ref = y_all{i} - 1.3372;
% 
%     % Shaded region first so curves stay on top
%     rectangle(ax, 'Position', [15 -30 1 20], ...
%         'FaceColor', [0.5 0.5 0.5], ...
%         'FaceAlpha', 0.25, ...
%         'EdgeColor', 'none', ...
%         'HandleVisibility', 'off');
% 
%     % Add no-gust quasi-steady line in panels (b) to (f)
%     if G_r ~= 0
%         plot(ax, t_nogust, y_nogust, '-', ...
%             'Color', nogust_color, ...
%             'LineWidth', lw_nogust, ...
%             'DisplayName', 'No gust');
%     end
% 
%     % Pandi et al. data
%     plot(ax, t_ref, y_ref, '--', ...
%         'Color', base_c, ...
%         'LineWidth', lw_plot, ...
%         'DisplayName', 'Pandi et al.');
% 
%     % Quasi-steady model
%     p = [l h rho_s rho_f l_CE e_x g G_r nu C_R]';
%     [~, y_, tSol, ~, ~, ~, ~] = ObjectiveFunction(p);
% 
%     % Marker time for this panel
%     t_mark = marker_times(i);
% 
%     if t_mark >= min(tSol) && t_mark <= max(tSol)
%         [~, marker_idx] = min(abs(tSol - t_mark));
%     else
%         marker_idx = [];
%     end
% 
%     plot(ax, tSol, y_, '-', ...
%         'Color', base_c, ...
%         'LineWidth', lw_plot, ...
%         'DisplayName', 'Quasi-steady');
% 
%     % ------------------------------
%     % Error calculation
%     % ------------------------------
%     t_min = 15;
%     t_max = 30;
% 
%     idx = (t_ref >= t_min) & (t_ref <= t_max);
%     t_ref_win = t_ref(idx);
%     y_ref_win = y_ref(idx);
% 
%     y_model_interp = interp1(tSol, y_, t_ref_win, 'linear', NaN);
% 
%     valid = ~isnan(y_model_interp);
%     dy = y_model_interp(valid) - y_ref_win(valid);
%     y_ref_valid = y_ref_win(valid);
% 
%     mae = mean(abs(dy));
%     rmse = sqrt(mean(dy.^2));
%     mean_ref = mean(abs(y_ref_valid));
%     percent_mae = (mae / mean_ref) * 100;
% 
%     results(i).G_r = G_r;
%     results(i).C_R = C_R;
%     results(i).mae = mae;
%     results(i).rmse = rmse;
%     results(i).percent_mae = percent_mae;
% 
%     fprintf('G_r = %d | C_R = %.2f | MAE = %.5f | RMSE = %.5f | %%MAE = %.2f%%\n', ...
%         G_r, C_R, mae, rmse, percent_mae);
% 
%     % Formatting per tile
%     title(ax, sprintf('$G_\\mathrm{R} = %d$', G_r), ...
%         'Interpreter', 'latex', ...
%         'FontSize', title_fs, ...
%         'FontWeight', 'bold');
% 
%     xlabel(ax, '$t$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     ylabel(ax, '$y$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     text(ax, -0.18, 1.06, sprintf('(%c)', 'a'+i-1), ...
%         'Units', 'normalized', ...
%         'Interpreter', 'latex', ...
%         'FontSize', panel_fs, ...
%         'FontWeight', 'bold');
% 
%     xlim(ax, [15 30]);
%     ylim(ax, [-30 -12]);
% 
%     set(ax, ...
%         'FontSize', tick_fs, ...
%         'LineWidth', lw_axes, ...
%         'TickLabelInterpreter', 'latex');
% 
%     legend(ax, 'show', ...
%         'Location', 'best', ...
%         'Interpreter', 'latex', ...
%         'FontSize', 11);
% end

% RGB = orderedcolors("gem");
% 
% figure;
% tiledlayout(3,2, 'TileSpacing','compact', 'Padding','compact');
% 
% CR_values = [0.814, 1.1, pi];
% CR_labels = {'0.814', '1.1', '\pi'};
% markers = {'o', 's', '^'};
% 
% GR_values = 0:5;
% t_all = {t_0, t_1, t_2, t_3, t_4, t_5};
% y_all = {y_0, y_1, y_2, y_3, y_4, y_5};
% 
% % One marker time for each tile (row = G_r) and each C_R (col = 1,2,3)
% marker_times = {
%     20, 24, 29;   % G_r = 0
%     24, 26, 20;   % G_r = 1
%     25, 29, 23;   % G_r = 2
%     24, 23, 24;   % G_r = 3
%     20, 25, 23;   % G_r = 4
%     20, 29, 27    % G_r = 5
% };
% 
% results = struct();
% 
% % Consistent formatting
% title_fs = 16;
% label_fs = 14;
% tick_fs  = 12;
% panel_fs = 14;
% lw_axes  = 1;
% lw_plot  = 1.4;
% 
% for i = 1:length(GR_values)
% 
%     G_r = GR_values(i);
% 
%     ax = nexttile;
%     hold(ax, 'on')
%     grid(ax, 'on')
%     box(ax, 'on')
% 
%     % Base colour for this gust ratio
%     base_c = RGB(i,:);
% 
%     % Three shades for the three C_R values
%     shades = [
%         base_c;
%         base_c + (1 - base_c)*0.35;
%         base_c + (1 - base_c)*0.65
%     ];
% 
%     % Reference data
%     t_ref = t_all{i};
%     y_ref = y_all{i} - 1.3372;
% 
%     % Shaded region first so curves stay on top
%     rectangle(ax, 'Position', [15 -30 1 20], ...
%         'FaceColor', [0.5 0.5 0.5], ...
%         'FaceAlpha', 0.25, ...
%         'EdgeColor', 'none', ...
%         'HandleVisibility', 'off');
% 
%     % Unsteady simulation: dashed, base colour
%     plot(ax, t_ref, y_ref, '--', ...
%         'Color', base_c, ...
%         'LineWidth', lw_plot, ...
%         'DisplayName', 'Pandi et al.');
% 
%     % Loop over C_R values
%     for j = 1:length(CR_values)
% 
%         C_R = CR_values(j);
%         c = shades(j,:);
% 
%         % Model
%         p = [l h rho_s rho_f l_CE e_x g G_r nu C_R]';
%         [x_, y_, tSol, ~, ~, ~, ~] = ObjectiveFunction(p);
% 
%         % One manual marker time for this tile and this C_R
%         t_mark = marker_times{i,j};
% 
%         % Convert marker time to nearest index in tSol
%         if t_mark >= min(tSol) && t_mark <= max(tSol)
%             [~, marker_idx] = min(abs(tSol - t_mark));
%         else
%             marker_idx = [];
%         end
% 
%         % Plot model
%         plot(ax, tSol, y_, '-', ...
%             'Color', c, ...
%             'LineWidth', lw_plot, ...
%             'Marker', markers{j}, ...
%             'MarkerIndices', marker_idx, ...
%             'MarkerSize', 6, ...
%             'MarkerFaceColor', c, ...
%             'MarkerEdgeColor', c, ...
%             'DisplayName', sprintf('$C_{\\mathrm{R}} = %s$', CR_labels{j}));
% 
%         % ------------------------------
%         % Error calculation
%         % ------------------------------
%         t_min = 15;
%         t_max = 30;
% 
%         idx = (t_ref >= t_min) & (t_ref <= t_max);
%         t_ref_win = t_ref(idx);
%         y_ref_win = y_ref(idx);
% 
%         y_model_interp = interp1(tSol, y_, t_ref_win, 'linear', NaN);
% 
%         valid = ~isnan(y_model_interp);
%         dy = y_model_interp(valid) - y_ref_win(valid);
%         y_ref_valid = y_ref_win(valid);
% 
%         mae = mean(abs(dy));
%         rmse = sqrt(mean(dy.^2));
%         mean_ref = mean(abs(y_ref_valid));
%         percent_mae = (mae / mean_ref) * 100;
% 
%         results(i,j).G_r = G_r;
%         results(i,j).C_R = C_R;
%         results(i,j).mae = mae;
%         results(i,j).rmse = rmse;
%         results(i,j).percent_mae = percent_mae;
% 
%         fprintf('G_r = %d | C_R = %s | MAE = %.5f | RMSE = %.5f | %%MAE = %.2f%%\n', ...
%             G_r, CR_labels{j}, mae, rmse, percent_mae);
%     end
% 
%     % Formatting per tile
%     title(ax, sprintf('$G_\\mathrm{R} = %d$', G_r), ...
%         'Interpreter', 'latex', ...
%         'FontSize', title_fs, ...
%         'FontWeight', 'bold');
% 
%     xlabel(ax, '$t$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     ylabel(ax, '$y$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     % Panel label outside title
%     text(ax, -0.18, 1.06, sprintf('(%c)', 'a'+i-1), ...
%         'Units', 'normalized', ...
%         'Interpreter', 'latex', ...
%         'FontSize', panel_fs, ...
%         'FontWeight', 'bold');
% 
%     xlim(ax, [15 30]);
%     ylim(ax, [-30 -12]);
% 
%     set(ax, ...
%         'FontSize', tick_fs, ...
%         'LineWidth', lw_axes, ...
%         'TickLabelInterpreter', 'latex');
% 
%     legend(ax, 'show', ...
%         'Location', 'best', ...
%         'Interpreter', 'latex', ...
%         'FontSize', 11);
% end

