% 
% % ============================================
% % Inputs
% % ============================================
% rho_s_vals = [1358, 1768];
% add_t_vals = [-1.28, -1.28];   % use one shift per rho_s if needed
% 
% % Reference data
% t_ref = x_curve1;
% y_ref = y_curve1;
% 
% % ============================================
% % Common formatting
% % ============================================
% title_fs = 16;
% label_fs = 14;
% tick_fs  = 12;
% panel_fs = 14;
% legend_fs = 11;
% lw_axes  = 1;
% lw_plot  = 1.2;
% 
% % ============================================
% % 1. Reference data by itself
% % ============================================
% figure;
% ax = axes;
% hold(ax,'on');
% box(ax,'on');
% grid(ax,'on');
% 
% plot(ax, t_ref, y_ref, 'r', 'LineWidth', lw_plot);
% 
% xlabel(ax, '$\hat{t}\,[\mathrm{s}]$', ...
%     'Interpreter', 'latex', ...
%     'FontSize', label_fs);
% 
% ylabel(ax, '$\alpha\,[\mathrm{deg}]$', ...
%     'Interpreter', 'latex', ...
%     'FontSize', label_fs);
% 
% xlim(ax, [0 5]);
% ylim(ax, [-190 30]);
% 
% set(ax, ...
%     'FontSize', tick_fs, ...
%     'LineWidth', lw_axes, ...
%     'TickLabelInterpreter', 'latex');
% 
% % ============================================
% % Preallocate storage
% % ============================================
% model_data = struct();
% shifted_data = struct();
% 
% % ============================================
% % Run model for each rho_s
% % ============================================
% for k = 1:length(rho_s_vals)
% 
%     rho_s = rho_s_vals(k);
% 
%     % Gravitational velocity scale
%     U_g = sqrt((rho_s/rho_f - 1) * g * h);
% 
%     l_CM = l_CE*(rho_s - rho_f)/rho_s; 
% 
% 
%     % Parameter vector
%     p = [l h rho_s rho_f l_CE e_x g G_r nu C_R]';
% 
%     % Run model
%     [x_, y_, tSol, v_yp, v_xp, omega, theta] = ObjectiveFunction(p);
% 
%     alpha = atan2((v_yp - omega * l_CM), v_xp); 
% 
%     alpha_unwrapped_rad = unwrap(alpha);
%     alpha_unwrapped_deg = rad2deg(alpha_unwrapped_rad);
% 
%     % Time in dimensional form
%     time = tSol * l / U_g;
% 
%     % Save unshifted model
%     model_data(k).rho_s = rho_s;
%     model_data(k).time = time;
%     model_data(k).alpha = alpha_unwrapped_deg;
% 
%     % Shifted model
%     t_model_shifted = time + add_t_vals(k);
% 
%     shifted_data(k).rho_s = rho_s;
%     shifted_data(k).time = t_model_shifted;
%     shifted_data(k).alpha = alpha_unwrapped_deg;
% end
% 
% % ============================================
% % 2. Model results vs reference data
% %    2 tiles: rho_s = 1358, 1768
% % ============================================
% figure;
% tl1 = tiledlayout(2,1, 'TileSpacing','compact', 'Padding','compact');
% 
% for k = 1:length(rho_s_vals)
% 
%     ax = nexttile;
%     hold(ax,'on');
%     box(ax,'on');
%     grid(ax,'on');
% 
%     plot(ax, t_ref, y_ref, 'r', ...
%         'LineWidth', lw_plot, ...
%         'DisplayName', 'Li et al.');
% 
%     plot(ax, model_data(k).time, model_data(k).alpha, 'b', ...
%         'LineWidth', lw_plot, ...
%         'DisplayName', 'Quasi-steady model');
% 
%     xlabel(ax, '$\hat{t}\,[\mathrm{s}]$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     ylabel(ax, '$\alpha\,[\mathrm{deg}]$', ...
%         'Interpreter', 'latex', ...
%         'FontSize', label_fs);
% 
%     title(ax, sprintf('$\\rho_\\mathrm{s} = %d\\ \\mathrm{kg\\,m^{-3}}$', rho_s_vals(k)), ...
%         'Interpreter', 'latex', ...
%         'FontSize', title_fs, ...
%         'FontWeight', 'bold');
% 
%     text(ax, -0.15, 1.05, sprintf('(%c)', 'a'+k-1), ...
%         'Units', 'normalized', ...
%         'Interpreter', 'latex', ...
%         'FontSize', panel_fs, ...
%         'FontWeight', 'bold');
% 
%     xlim(ax, [0 5]);
%     ylim(ax, [-190 40]);
% 
%     set(ax, ...
%         'FontSize', tick_fs, ...
%         'LineWidth', lw_axes, ...
%         'TickLabelInterpreter', 'latex');
% 
%     legend(ax, 'show', ...
%         'Location', 'best', ...
%         'Interpreter', 'latex', ...
%         'FontSize', legend_fs);
% end
